INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (8721,'I\'ve got the goods. I\'ll be hiding up the river from crystal lake, near the wall. If you send one of your agents for the pickup, make sure they stay out of sight!\n\n- Cutty',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (8816,'<The text of the page is mostly soiled with blood, but you can make out a name>\n\nGakin',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (8828,'<The page is singed in multiple spots, as if someone had hastily tried to burn it. Some of what remains is legible>\n\nAda,\n\nI\'m pleased to hear -------- island at the darkened bank. ----- One of our agents ------------ pass phrase ----\n\n\"As one candle is snuffed out, another is lit.\"\n\n- Mitchells',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (8871,'I\'ve got the goods. I\'ll be hiding west of Tiragarde keep, beneath a tree with dark leaves. If you send one of your agents for the pickup, make sure they stay out of sight!\n\n- Ba\'so',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (8887,'I\'ve got the goods. I\'ll be hiding near Misty Pine Refuge, by the old boat. If you send one of your guys for the pickup, make sure they stay out of sight!\n\n- Blackrat',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (8888,'<The text of the page is mostly soiled with blood, but you can make out a name>\n\nCarendin',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9036,'The getaway plan is a go. We leave tonight.\n\nThere\'s just one last thing. I\'ve hidden a stash of equipment up in the Dagger Hills, in the back entrance to the Deadmines. The key to the stash is in this envelope. Hopefully, we won\'t need it, but you never know.\n\nI\'m so relieved we can finally leave this Defias business behind us. By this time tomorrow, we\'ll be kicking back on the beaches of Stranglethorn. \n\nYours always,\nEmily',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9122,'Brother Esolon,\n\nShould you need access to the reliquary, I\'ve hidden a key in the graveyard. It is inside a stone coffer; beneath the floor of the northern mausoleum.\n\nThere is a mechanism to raise the coffer. To activate it, you must sit on the two benches between the pairs of statues on either side of the graveyard.\n\nPlease treat this information as highly privileged.\n\nBlessings,\nBrother Seramus',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9136,'< The manuscript shows a map of three crystals along the Zoram Strand. An ordered path is traced between the crystals; going from south to north. Next to each crystal is a drawing depicting an explosion of arcane magic. >',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9194,'By order of Grand Crusader Dathrohan: \n\nThe heretic known as Aeonas the Quiet is hereby condemned for the high crime of consorting with demons and the undead, forsaking the light, larceny, and murder. This vile creature is known to have slain no less than two of our stalwart brothers of the light while perpetrating the theft of important Scarlet Crusade property. When found, the heretic himself is to be transported to the Monastery in Tirisfal for questioning and execution. Should any parcels or artifacts be in his possession when apprehended, they are to be returned to the Grand Crusader with all haste as evidence. \n\nIf captured, Aeonas must be gagged and no one save the High Inquisitor may speak with him, lest his insidious lies sow chaos and doubt in otherwise righteous hearts. Be wary brothers and sisters, as there is no way of knowing what sort of vile magics Aeonas may have bargained for in his fell dealings with the enemies of the light.',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9217,'Due to your coven\'s staggering ineptitude not one but two groups of interlopers were able to penetrate your defenses, inflict heavy casualties, and steal our property. I will deal with the Scarlet Crusade, but I need your pitiful coven to muster the competence to track down the paladin and his accomplice and recover...\n\n<The letter is torn and the rest is missing>',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9236,'Our spies tell us that SI:7 and the Silver Hand has taken the bait and your target should be inbound to you. Find out what they know, and then see to it that you dispose of them quietly, outside the city preferably. We must see these meddlers dead and our property returned to us by any means necessary. Do not fail.',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9254,'Day 14:\n\nI believe I\'ve discovered a way to undo the corruption brought here by the Satyr: A tincture brewed from their own blight!\n\nUsing samples of the nearby Satyrweed, an extract could be made that wards against full-on corruption by exposure to a smaller amount. One could think of it almost like an anti-venom.\n\nI\'d like to test my cure on the local wildlife, but the beasts here are too aggressive. If only I could tranquilize them somehow.',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9257,'<a rough image of a dwarf face takes up most of the note. A few lines are written below it>\n\nKnown trespasser! Spy! Interrogating OUR citizens!\n\nVisiting pairs to Shadowforge city report briefly encountering a dwarf with a strange accent, repeatedly heard saying \"they are not the two for us\"\n\nReport to any enlisted Anvilrage officer with any information!\n\nTake heed, no large groups have encountered this covert guest. \nBe alert!',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9258,'The calm comes before the storm.',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9523,'...and that\'s how I found the Ashbringer and used it to totally pwn noobs in Warsgon Gulch.',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9552,'We need more willing sacrifices!\n\nThere must be some sort of trick to that altar - it\'s yielded nothing so far.\n\nReport back to the Serpent\'s Coil when you find something useful.',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9585,'The crystal has shown me visions of its past. It was shattered from a perfect whole, a thing of glorious divine power.\n\nThe vicious conflicts between the races of Azeroth continue to grow. If the shards are reunited now, they could be wielded as a weapon of terrifying destruction.\n\nIf you seek to reunite the shards, I beseech you - use their power to unite Azeroth\'s children, not to wage further war.',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9586,'Under the protection of the shard of Light, we fled to the crypt and barricaded ourselves inside. But Wescott and Billina left to find supplies, and took the shard with them for protection. After three days they have not returned, and without the shard\'s power the Scourge will soon be upon us...',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (9955,'Dear future me, don\'t forget the bread this time.\n\n- 2 Gallons of Ice Cold Milk\n- 20 Wedges of Finely Aged Cheddar (the rats keep eating it all)\n- 1 Delicious Chocolate Cake\n- Actually, make that 2 cakes\n- 4 Hazards of Goblin Rocket Fuel\n- 2 Thorium Tubes\n- 1 Truesilver Transformer\n- <the writing is smudged beyond legibility>\n- 2 Gyrochronatoms',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10175,'My dearest Tabitha,\n\nHow strange it is to foretell my own death. I\'ve written this note as I do not know the hour when fate will claim me and although I know that this is a poor apology for a proper speech, my quill fails in its attempt to convey my pain for departing from you.\n\nEvery day I wake to the sorrow I failed to protect you from. I am sorry I could not protect our dear boy and I am sorry that my grieving has fallen into a trap from which it cannot escape.\n\nYou are my love, and my confidante and my life counted for more than it could alone. Every week when I venture into the ruins of our once proud home, I fear it would be my last, and every time I am thankful I have you to return to.\n\nI pray we are reunited, if even for a moment.',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10178,'Oi, you, $C. Get off yer duff and come see me behind the abbey. A soft, green hunter such as yerself canna hope to survive let alone thrive in this land without some guidance, and ol\' Tordrin is here to provide it, if ye have the guts! \n\n\nTordrin Stemblade, (extremely handsome) Hunter Trainer',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10482,'We will attack the city of Brill just before dawn. The ancillary force will set the zeppelin tower aflame as a distraction. Once the fire is lit and the city defenders are drawn away, the main force led by the lieutenant will engage from the north. The Magistrate and civilians are the primary targets. Destroy all you see, and incinerate the bodies.\n\nThey say that the Forsaken feel no fear. We will put the fear of the light back into them, brothers and sisters. For Lordaeron!',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10483,'Brother Haalien,\n\nIt is time to prove your worth to the Al\'Aketh! Go into Shadowgale to find the pylon. You have conveyed your concerns about the druids and the highest in our order have heard you.\n\nTake these faithful soldiers with you in your righteous mission. Kill the druids swiftly lest they interfere with our plans. We have eyes and ears in Valanaar that will confirm when you have been successful.\n\nThe time of reckoning is at hand! None shall be able to stop the ushering!\n\n-N',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10572,'Corporal Adamore,\n\nAt first light you are to muster a force of no more than 10 marines and report to a bounty hunter by the name of Terry Longdrink. You will be joining him in pursuit of a dangerous deserter whom you should presume to be armed and hostile.\n\nThis bounty hunter was a trusted ally of the Lord Admiral before his passing, and I expect you to show Longdrink the same deference you\'d show any superior officer. \n\n--Lieutenant Benedict',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10589,'<A crude rendition of the landscape, with a clear point of interest indicated.>\n\nMogodun- z kost a-hine\nta golg\ngar thon- kha z\'ta gor weard-hald\n\n<The map is in too poor of condition to make out any other writing.>',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10635,'It is encouraging to hear that the new magic that our lord provided has performed above expectations. If the venom is as effective as you claim, it will be a powerful tool for us to use in the conflict to come. I told you that there was much to be learned from the undead littering our mountain. Don\'t worry, I won\'t hold your initial skepticism against you.\n\nFinish your business there and return to the summit with your samples. No need to cull the beasts. If they spread to neighboring areas, they will only sow chaos, confusion and fear. This will serve to further the Pact\'s goals, in the end.\n\nGood work. The Wild King will surely be pleased with what you have accomplished.',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10642,'The tunnels have reached the bluffs within Thousand Needles and our preparations have gone unseen, but we must act swiftly. We cannot allow those fools at the Freewind Post to discover us before we are ready to move.\n\nSend your shaman. With all that Hirzek has accomplished we are ready to begin.\n\nThe storm will rage, the ground will rumble and the tide shall rise, leaving only carcasses to animate in our wake. Their bones will blaze a trail into...\n\n\n<The note ends abruptly at the bottom of the torn page.>',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10759,'Tide,$B$BHope you meant what you said about getting to the bottom of this mess. I waited here all day, I\'ll return on the next blue moon. This kind of work is much faster with two people.$B$BIf I can\'t make it back, you\'ll have to finish what was started.$B$BSilver',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10842,'Mr. Alexston of Stormwind,\n\nI must congratulate you on the long journey restoring the city of Stormwind. Many whose path crosses Auberdine speak well of its grandeur and sound foundations. It is this success that bid me send you this message.\n\nAuberdine has found its place in this world by the sea. Where we were once isolated, we now find hope carried by the very winds that batter our shores.\n\nThis courier represents one such traveler the winds bore to me. I hope that they may aid your people as they have mine.\n\nIn return, I ask that you might send supplies and labor to Auberdine, such that we might bolster the city against the wrath of this world that has taken so much from us.\n\n-- Thundris Windweaver, Elder of Auberdine',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10843,'I know how this letter will find you, and I am truly sorry about that, elder.\n\nWithout a doubt, I will send any able-bodied adventurers I can through your fine town. I hope their impact will make up for the lack of other support I can bring at this time.\n\nOur lands are pressured by a great many enemies. I\'m sure you are no stranger to that world yourself, but it has painfully drained what resources we have.\n\nShould that change, I would love to help, but even then there are many projects close to home that will demand priority.\n\nHold strong. We\'re all in this together.\n\n-- Baros Alexston\nCity Architect, Stormwind',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10940,'Arch Druid,\n\n$N has done a great service for the land today. The Winterhoof, Thunderhorn, and Wildmane wells have been cleansed of the goblins\' poisons thanks to their bravery.\n\nWith time, the rejuvenated waters will nourish all who walk upon Mulgore\'s great plains, and the land will heal. Earth Mother be praised.\n\nIf you are willing, I request you provide a reward commensurate with their efforts, on behalf of all in Bloodhoof Village.\n\nWith great reverence,\n\nMull Thunderhorn',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10944,'Tarrel my beloved,\n\nNot a day goes by that I don\'t lose myself thinking of those bronze braids, that bellowing laugh, or those rippling forearms.\n\nYou must come to me in Auberdine on the next ship. We belong together--you know it to be true if you search your heart!\n\nYours if you\'ll have me,\n\nHollee',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10950,'While you may be a refugee who has come to Ironforge out of desperation, the Light never turns away those in need. Over time your devotion will deepen and you\'ll learn to feel the warmth of the Light. Our cousins among the gnomes are as welcome among our ranks as any stout dwarf.\n\nI can tell that you have the gift of channeling the Light. This is a special quality and one that you should nurture.\n\nFind me when ya have the time. I\'ll be in the back of Anvilmar, just up the hill.\n\n- Branstock Khalder, Priest Trainer',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10951,'Your nascent skills are too rudimentary to realize that this tablet is suffused with powerful curses of suffering to prevent any unwanted eyes from reading it.\n\nThrough my power I have felt your first steps toward a tenuous connection with the Twisting Nether, and now I reach out to offer you the boon of mentorship. With my guidance, you will learn to command demons and call down the flames from beyond the mortal coil.\n\nSeek me out in the depths of the Den once you\'ve found your way around. I would speak to you about important matters.\n\n-Nartok, Warlock Trainer',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10952,'You see what other orcs cannot see, you feel the pulse of the universe around you. You got the touch of magic, and it be time to learn how to control it.\n\nYou find Mai\'ah when you be ready. She teach you much about magic and the spells you need to destroy those dat stand against you.\n\nMai\'ah be near the Den in the Valley of Trials. You come, you find her, then you be strong. Then you show other mages how magic bends to your will... not the other way \'round.',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10953,'You already felt the call of something greater than yourself, and that\'s the call of the elements. We dwarves have a strong connection to earth, but with the right training, you can learn to speak to all of the elements. The elementals can be demanding and challenging, but I\'m here to guide you in learning how to communicate with them. Come find me in Anvilmar and I\'ll teach you how to listen to the elements, and how to get them to listen to you.\n\n- Teo Hammerstorm, Shaman Trainer',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10958,'<As you touch the glowing crystal a draft of wind stirs around you, carrying the faint hint of spoken words.>\n\nThe High Order has been watching you, $N, and we see great promise in your abilities.\n\nThe Wind Spirits have left Zephras Isle, and now more than ever, promising mages like yourself are needed. If our people are to find the self-reliance to survive this crisis, we must use our knowledge of the arcane to uncover the secrets of this realm.\n\nSeek me out in Thendal Village, on the ground floor of the great tree. We will begin your training in earnest.\n\n-Dorii Brightwhisper, Mage Trainer',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10959,'<As you touch the glowing crystal a draft of wind stirs around you, carrying the faint hint of spoken words.>\n\nThe Windshapers have been watching you closely, and the time has come for you to take your next steps as a shaman.\n\nThe wind spirits have vanished from Zephras Isle and the burden falls to us to brave the dangers of the elemental plane and bring them home. There is no more sacred duty, and our survival depends on it.\n\nSeek me out in Thendal Village, near the town center. I will see to it that you are trained.\n\n-Windshaper Boro, Shaman Trainer',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10960,'$N, you\'ve got a good sword arm and I\'ve taken notice. \n\nThings are a fine mess here on Zephras Isle, no doubt about it. We need our fighting shen\'dorei in top form if we are to survive what\'s to come. It\'s time for you to stop playing at being a proper warrior, and actually become one.\n\nFind me inside the base of the watchtower here in Thendal Village. I\'ll see to it you are properly trained.\n\n\n-Blademaster Ren, Warrior Trainer',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10961,'Greetings, $N,\n\nSince the elemental wind spirits vanished, Zephras has been on a deadly precipice. The birds, the beasts, and even the roots beneath our feet call to us for aid.\n\nSeek me out on the ground floor of the great tree here in Thendal Village. I will counsel and train you in the druidic arts.\n\n-Xyton Silverwind, Druid Trainer',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10962,'Greetings, $N,\n\nYou\'ve shown great promise as a hunter, and I\'d like to ensure that you receive proper guidance and training. \n\nThe rangers do a good job of keeping the wilds in check here in Thendal Grove, but beyond our borders... well, the same can\'t be said.\n\nCome find me near the center of the village as soon as you are able. The wilds are calling.\n\n-Tai\'ree Farsight, Hunter Trainer',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10963,'I\'ll make this short, $N.\n\nYou\'ve got a slyness and grace to you that I respect, and I\'ve been keeping my eye on you. \n\nSlyness and grace aren\'t always enough to keep you alive though. If you want to learn to be a proper rogue then I can teach you.\n\nCome find me inside the watchtower.\n\n-Akeri Duskblade, Rogue Trainer',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10965,'Welcome back, $N. \n\nI understand all too well the shock that one feels when finding themselves in the situation you now find yourself in. The fact that you have made it this far sets you apart from many other newly risen paladins.\n\nYou will find that the hardest part about your new life will be in rediscovering what you lost in life...and enduring the pain it causes you.\n\nSpeak with me in Deathknell, and I will help you find the resolve to take your first steps.\n\n-Aramis Hammerhand, Paladin Trainer',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (10987,'Find what the Alliance have dug up. We know what lies in these hills. With this, we will bring a worthy tribute to Rend.\n\nChieftain Nek\'rosh',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (11027,'Scourge have continued to slip through both the Bulwark and the eastern waystation, their numbers growing by the day. How such a failure in our defenses is allowed to persist is beyond my reckoning.\n\nAs noted in my previous reports, the paltry allotment of guards assigned to Brill is insufficient for what comes for us. It is not a matter of if we will be overrun, but when. And once Brill falls, it shall serve as the perfect staging ground to lay siege to the Undercity.\n\nIt is not my recommendation, but my demand that reinforcements be dispatched from their luxurious posts in the Undercity to defuse the situation while we still possess the opportunity.\n\n--Deathguard Dillinger',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (11028,'Executor Zygand,\n\nIt is my opinion that the Scourge we see further inland are not due to our defenses failing. I have witnessed our forces at the Bulwark and eastern waypoint for some time now, and it would take a veritable army to break through.\n\nRather, I suspect they are being newly created by some unseen enemy within our borders. I will continue to pull on this thread, in hopes that we may stop these occurrences at the source.\n\n--Kristof',0,0,0,0);
INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `PlayerConditionID`, `Flags`, `VerifiedBuild`) VALUES (11029,'<Impressively, there is a barely legible carving in the remaining skin of the apple.>\n\nApple yum yum. Me pick flowers now.',0,0,0,0);
